using System;using System.Drawing;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using PersonalIme;
class LifecycleUiTests {
 static int count;static void Check(bool b,string label){if(!b)throw new Exception(label);count++;Console.WriteLine("PASS "+label);}static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Pump(int n){var end=DateTime.UtcNow.AddMilliseconds(n);while(DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(5);}}
 [STAThread]static int Main(){Native.SetProcessDPIAware();Control.CheckForIllegalCrossThreadCalls=true;Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();int result=0;using(var host=new Form{ShowInTaskbar=false,Opacity=0,Size=new Size(1,1),Text="Yandu lifecycle dispatcher"}){host.Shown+=delegate{try{Hotkeys();Notices();CaptureSurface();SensitiveCapture();Console.WriteLine("OK "+count+" lifecycle UI and shared screenshot checks");}catch(Exception ex){Console.WriteLine("FAIL "+ex.GetType().Name+": "+ex.Message+"\n"+ex.StackTrace);result=1;}finally{host.Close();}};Application.Run(host);}return result;}
 static void Hotkeys(){Check(CaptureShortcut.Normalize("alt+ctrl+z")=="Ctrl+Alt+Z","shared shortcut normalized");Check(CaptureShortcut.Normalize("")=="","blank shortcut disables binding");bool rejected=false;try{CaptureShortcut.Parse("Ctrl+Alt");}catch(ArgumentException){rejected=true;}Check(rejected,"modifier-only shortcut rejected");using(var host=new Form()){var h=host.Handle;var key=CaptureShortcut.Parse("Ctrl+Shift+F23");Check(Native.RegisterHotKey(h,1189,key.Modifiers,key.Key),"isolated conflict fixture registered");try{Check(!CaptureShortcut.Probe(h,key.Text),"occupied shortcut is refused without stealing");}finally{Native.UnregisterHotKey(h,1189);}Check(CaptureShortcut.Probe(h,key.Text),"released shortcut becomes available");}int fields=0;foreach(var f in typeof(Settings).GetFields())if(f.Name.IndexOf("Hotkey",StringComparison.OrdinalIgnoreCase)>=0)fields++;Check(fields==1,"one shared screenshot shortcut setting only");var cfg=new Settings();cfg.SetKey("fixture-only-key");using(var engine=new Translator(new MockHandler()))using(var settings=new SettingsForm(cfg,engine,delegate{})){settings.CaptureShortcutAvailable=value=>true;Field<TextBox>(settings,"captureKey").Text="Ctrl+Alt+F22";var read=typeof(SettingsForm).GetMethod("Read",BindingFlags.Instance|BindingFlags.NonPublic);var result=(Settings)read.Invoke(settings,null);Check(result.ScreenshotHotkey=="Ctrl+Alt+F22","translation settings store the single shared custom shortcut");settings.CaptureShortcutAvailable=value=>false;bool conflict=false;try{read.Invoke(settings,null);}catch(TargetInvocationException ex){conflict=ex.InnerException is ArgumentException;}Check(conflict,"conflicting shortcut cannot pass settings validation");}}
 static void Notices(){var release=new ReleaseInfo{tag_name="v9.0.0",Version=new Version(9,0,0,0),Installer=new ReleaseAsset()};var state=new UpdateNoticeState();Check(state.Due(DateTime.UtcNow)&&state.ShouldNotify(release),"newer release eligible on first check");state.LastCheckUtc=DateTime.UtcNow;Check(!state.Due(DateTime.UtcNow.AddHours(1)),"automatic checks throttled to 24 hours");state.IgnoredVersion="v9.0.0";Check(!state.ShouldNotify(release),"ignored version does not prompt again");string file=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"update-state-fixture-"+Guid.NewGuid().ToString("N")+".json");try{state.Save(file);var loaded=UpdateNoticeState.Load(file);Check(loaded.IgnoredVersion=="v9.0.0"&&!loaded.Due(DateTime.UtcNow.AddHours(1)),"ignored version and daily check state survive restart");}finally{System.IO.File.Delete(file);}release.Version=Updates.CurrentVersion;Check(!state.ShouldNotify(release),"same version never offers upgrade");release.Version=new Version(9,0,0,0);int dismissed=0,downloads=0;
  using(var notice=new UpdateNotice(release,(p,t)=>{downloads++;return Task.FromResult(0);},()=>dismissed++)){notice.Show();Pump(50);Check(!notice.ShowInTaskbar&&notice.Right<=Screen.PrimaryScreen.WorkingArea.Right&&notice.Bottom<=Screen.PrimaryScreen.WorkingArea.Bottom,"update notice anchored inside bottom-right work area");Field<Button>(notice,"ignore").PerformClick();Check(dismissed==1&&downloads==0,"ignore closes notice without downloading");}
  using(var notice=new UpdateNotice(release,(p,t)=>{downloads++;return Task.FromResult(0);},()=>dismissed++)){notice.Show();Pump(30);Field<Button>(notice,"cancel").PerformClick();Check(downloads==0&&dismissed==1,"cancel closes without download or persistent ignore");}
  using(var notice=new UpdateNotice(release,(p,t)=>{downloads++;return Task.FromResult(0);},()=>dismissed++)){notice.Show();Pump(30);Field<Button>(notice,"upgrade").PerformClick();Pump(100);Check(downloads==1,"upgrade dispatches download and verified install flow exactly once");}
 }
 static void SensitiveCapture(){foreach(bool changed in new[]{false,true}){var bounds=SystemInformation.VirtualScreen;var area=Screen.PrimaryScreen.WorkingArea;var handler=new MockHandler();using(var translator=new Translator(handler))using(var window=new ScreenTranslation(new Settings(),translator,new Bitmap(bounds.Width,bounds.Height),bounds,new Rectangle(area.Left+50,area.Top+100,160,50),null,t=>Task.FromResult("password=fixture-only"),null,true,true)){window.Show();Pump(100);if(changed)Clipboard.SetText("replacement clipboard fixture");Field<Button>(window,"retry").PerformClick();Pump(150);Check(Field<bool>(window,"blocked")&&handler.Calls==0&&(changed?Clipboard.GetText()=="replacement clipboard fixture":!Clipboard.ContainsImage()),changed?"sensitive block preserves newer user clipboard contents":"sensitive block removes only its own copied screenshot");window.Close();}}}
 static void CaptureSurface(){Check(SynchronizationContext.Current is WindowsFormsSynchronizationContext,"test uses real application UI synchronization context");var bounds=SystemInformation.VirtualScreen;var area=Screen.PrimaryScreen.WorkingArea;var region=new Rectangle(area.Left+50,area.Top+80,130,60);var image=new Bitmap(bounds.Width,bounds.Height);using(var g=Graphics.FromImage(image)){g.Clear(Color.Blue);g.FillRectangle(Brushes.Red,region.Left-bounds.Left,region.Top-bounds.Top,region.Width,region.Height);}var handler=new MockHandler();int ocr=0;var cfg=new Settings();cfg.SetKey("fixture-only-key");using(var translator=new Translator(handler))using(var window=new ScreenTranslation(cfg,translator,image,bounds,region,null,t=>{ocr++;return Task.FromResult("你好");},null,true,true)){
   window.Show();Pump(180);Check(Clipboard.ContainsImage(),"shared capture automatically places bitmap on clipboard");using(var pasted=Clipboard.GetImage())using(var pixels=new Bitmap(pasted)){Check(pasted.Size==region.Size&&pixels.GetPixel(10,10).R>220,"clipboard image has exact selected size and pixels");}Check(ocr==0&&handler.Calls==0,"plain screenshot performs no OCR or API call");Check(!Field<Panel>(window,"card").Visible&&Field<Button>(window,"retry").Text=="翻译","same capture surface offers explicit translation action");Field<Button>(window,"retry").PerformClick();var until=DateTime.UtcNow.AddSeconds(3);do{Pump(25);}while(Field<CancellationTokenSource>(window,"request")!=null&&DateTime.UtcNow<until);Check(ocr==1&&handler.Calls==1&&Field<bool>(window,"ready")&&Field<TextBox>(window,"english").Text=="Hello.","translation action reuses capture and runs recognition once");Check(Field<Button>(window,"copy").Text=="复制译文","translated result switches to text copy action");window.Close();}
 }
